interface AnalyticsData {
  visitors: number;
  pageViews: number;
  bounceRate: number;
}

interface Notification {
  id: string;
  message: string;
  type: 'info' | 'warning' | 'error';
  timestamp: string;
}

interface SettingsData {
  theme: 'light' | 'dark';
  notificationsEnabled: boolean;
  language: string;
}

async function getDashboardData() {
  const API_BASE = process.env.API_BASE_URL || 'http://localhost:3000';

  try {
    const [analyticsRes, notificationsRes, settingsRes] = await Promise.all([
      fetch(`${API_BASE}/api/analytics`),
      fetch(`${API_BASE}/api/notifications`),
      fetch(`${API_BASE}/api/settings`)
    ]);

    if (!analyticsRes.ok || !notificationsRes.ok || !settingsRes.ok) {
      throw new Error('Failed to fetch data');
    }

    const [analytics, notifications, settings] = await Promise.all([
      analyticsRes.json(),
      notificationsRes.json(),
      settingsRes.json()
    ]) as [AnalyticsData, Notification[], SettingsData];

    return { analytics, notifications, settings };
  } catch (error) {
    console.error('Error fetching dashboard data:', error);
    // Return mock data for build time or when API is unavailable
    return {
      analytics: {
        visitors: 1250,
        pageViews: 3400,
        bounceRate: 45
      },
      notifications: [
        { id: '1', message: 'System update scheduled', type: 'info', timestamp: new Date().toISOString() },
        { id: '2', message: 'New user registration', type: 'warning', timestamp: new Date().toISOString() }
      ] as Notification[],
      settings: {
        theme: 'light',
        notificationsEnabled: true,
        language: 'en'
      } as SettingsData
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="p-4 space-y-6">
      <h2 className="text-2xl font-bold mb-4">Dashboard Overview</h2>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Analytics Section */}
        <div className="border p-4 rounded-lg shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Analytics</h3>
          <ul className="space-y-2">
            <li>Visitors: {analytics.visitors}</li>
            <li>Page Views: {analytics.pageViews}</li>
            <li>Bounce Rate: {analytics.bounceRate}%</li>
          </ul>
        </div>

        {/* Notifications Section */}
        <div className="border p-4 rounded-lg shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Notifications</h3>
          <ul className="space-y-2">
            {notifications.map((notification) => (
              <li key={notification.id} className="text-sm p-2 bg-gray-50 rounded">
                {notification.message}
              </li>
            ))}
            {notifications.length === 0 && <li className="text-gray-500">No new notifications</li>}
          </ul>
        </div>

        {/* Settings Section */}
        <div className="border p-4 rounded-lg shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Settings</h3>
          <ul className="space-y-2">
            <li>Theme: {settings.theme}</li>
            <li>Notifications: {settings.notificationsEnabled ? 'On' : 'Off'}</li>
            <li>Language: {settings.language}</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

